with by_dimension as (select p.country, s.event_type, count(*) as rows_total, round(avg(s.duration_sec), 2) as avg_duration_sec, grouping_id() as gid from web_events s left join sessions p on s.session_id = p.id group by grouping sets ((p.country, s.event_type), (p.country), ())) select country, event_type, rows_total, avg_duration_sec, case when event_type rlike '^(add_to_cart|click)$' then 'CORE' else 'GROUP_A' end as event_type_zone from by_dimension
